 LAST LIMIT ?) AS "_stage_3" ORDER BY tupleElement("__os_order_2_0", 1) ASC NULLS LAST, tupleElement("__os_order_2_0", 2) ASC NULLS LAST, "__os_order_2_tie_0" DESC NULLS LAST, "__os_order_2_tie_1" DESC NULLS LAST, "__os_order_2_tie_2" DESC NULLS LAST
